// types/media.types.ts

export interface ListUserImagesParams {
  limit?: number;
  cursor?: string;
  prefix?: string;
  signed?: boolean;
  expiresIn?: number;
}

export interface MediaItem {
  key: string;
  url: string;
  signedUrl?: string;
  size: number;
  lastModified: string;
  contentType?: string;
}

export interface ListUserImagesResponse {
  items: MediaItem[];
  nextCursor?: string;
  hasMore: boolean;
}

export enum ImageFolder {
  ALL = '',
  COVERS = 'covers/',
  ACCOUNTS = 'accounts/',
  INSPIRATIONS = 'inspirations/',
}


// services/api/media.service.ts

import { apiClient } from './client';
import { ListUserImagesParams, ListUserImagesResponse } from '@/types/media.types';

export const mediaService = {
  /**
   * Fetch user images from S3
   * @param params - Query parameters for filtering and pagination
   * @returns Promise with image list and pagination info
   */
  async listUserImages(params: ListUserImagesParams = {}): Promise<ListUserImagesResponse> {
    const queryParams = new URLSearchParams();

    if (params.limit !== undefined) {
      queryParams.append('limit', params.limit.toString());
    }
    if (params.cursor) {
      queryParams.append('cursor', params.cursor);
    }
    if (params.prefix) {
      queryParams.append('prefix', params.prefix);
    }
    if (params.signed !== undefined) {
      queryParams.append('signed', params.signed.toString());
    }
    if (params.expiresIn !== undefined) {
      queryParams.append('expiresIn', params.expiresIn.toString());
    }

    const response = await apiClient.get<ListUserImagesResponse>(
      `/api/media/images?${queryParams.toString()}`
    );

    return response.data;
  },
};


// hooks/useUserImages.ts

import { useInfiniteQuery } from '@tanstack/react-query';
import { mediaService } from '@/services/api/media.service';
import { ListUserImagesParams } from '@/types/media.types';

export function useUserImages(params: Omit<ListUserImagesParams, 'cursor'> = {}) {
  return useInfiniteQuery({
    queryKey: ['user-images', params],
    queryFn: ({ pageParam }) =>
      mediaService.listUserImages({
        ...params,
        cursor: pageParam,
      }),
    getNextPageParam: (lastPage) =>
      lastPage.hasMore ? lastPage.nextCursor : undefined,
    staleTime: 5 * 60 * 1000, // 5 minutes
  });
}

// Alternative with SWR
import useSWRInfinite from 'swr/infinite';

export function useUserImagesSWR(params: Omit<ListUserImagesParams, 'cursor'> = {}) {
  const getKey = (pageIndex: number, previousPageData: any) => {
    if (previousPageData && !previousPageData.hasMore) return null;

    const cursor = previousPageData?.nextCursor;
    return ['user-images', { ...params, cursor }];
  };

  return useSWRInfinite(
    getKey,
    ([_, fetchParams]) => mediaService.listUserImages(fetchParams as ListUserImagesParams),
    {
      revalidateFirstPage: false,
    }
  );
}


// components/ImageGallery.tsx

import React from 'react';
import { useUserImages } from '@/hooks/useUserImages';
import { ImageFolder } from '@/types/media.types';

interface ImageGalleryProps {
  folder?: ImageFolder;
  onImageSelect?: (imageUrl: string) => void;
  allowMultiSelect?: boolean;
}

export const ImageGallery: React.FC<ImageGalleryProps> = ({
  folder = ImageFolder.ALL,
  onImageSelect,
  allowMultiSelect = false,
}) => {
  const {
    data,
    fetchNextPage,
    hasNextPage,
    isLoading,
    isError,
    error,
  } = useUserImages({
    prefix: folder,
    limit: 24,
    signed: true, // Use signed URLs for security
    expiresIn: 3600, // 1 hour
  });

  if (isLoading) {
    return <ImageGallerySkeleton />;
  }

  if (isError) {
    return <ErrorState error={error} />;
  }

  const allImages = data?.pages.flatMap((page) => page.items) ?? [];

  if (allImages.length === 0) {
    return <EmptyState />;
  }

  return (
    <div className="image-gallery">
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
        {allImages.map((image) => (
          <ImageCard
            key={image.key}
            image={image}
            onSelect={onImageSelect}
          />
        ))}
      </div>

      {hasNextPage && (
        <button
          onClick={() => fetchNextPage()}
          className="load-more-btn"
        >
          Load More
        </button>
      )}
    </div>
  );
};


// components/ImageFolderFilter.tsx

import React from 'react';
import { ImageFolder } from '@/types/media.types';

interface ImageFolderFilterProps {
  activeFolder: ImageFolder;
  onFolderChange: (folder: ImageFolder) => void;
}

export const ImageFolderFilter: React.FC<ImageFolderFilterProps> = ({
  activeFolder,
  onFolderChange,
}) => {
  const folders = [
    { value: ImageFolder.ALL, label: 'All Images' },
    { value: ImageFolder.COVERS, label: 'Cover Images' },
    { value: ImageFolder.ACCOUNTS, label: 'Account Avatars' },
    { value: ImageFolder.INSPIRATIONS, label: 'Inspirations' },
  ];

  return (
    <div className="flex gap-2 border-b mb-6">
      {folders.map((folder) => (
        <button
          key={folder.value}
          onClick={() => onFolderChange(folder.value)}
          className={`px-4 py-2 ${
            activeFolder === folder.value
              ? 'border-b-2 border-blue-500 text-blue-600'
              : 'text-gray-600 hover:text-gray-900'
          }`}
        >
          {folder.label}
        </button>
      ))}
    </div>
  );
};


// components/ErrorState.tsx

import React from 'react';

interface ErrorStateProps {
  error: any;
  onRetry?: () => void;
}

export const ErrorState: React.FC<ErrorStateProps> = ({ error, onRetry }) => {
  const getErrorMessage = () => {
    if (error?.response?.status === 401) {
      return 'Please sign in to view your images.';
    }
    if (error?.response?.status === 500) {
      return 'Unable to load images. Please try again later.';
    }
    return 'Something went wrong loading your images.';
  };

  return (
    <div className="error-state text-center py-12">
      <div className="text-red-500 mb-4">
        <svg className="w-16 h-16 mx-auto" /* error icon */ />
      </div>
      <h3 className="text-lg font-semibold mb-2">Oops!</h3>
      <p className="text-gray-600 mb-4">{getErrorMessage()}</p>
      {onRetry && (
        <button
          onClick={onRetry}
          className="btn btn-primary"
        >
          Try Again
        </button>
      )}
    </div>
  );
};


// components/ImageGallerySkeleton.tsx

export const ImageGallerySkeleton = () => {
  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
      {Array.from({ length: 8 }).map((_, i) => (
        <div key={i} className="animate-pulse">
          <div className="bg-gray-200 aspect-square rounded-lg" />
        </div>
      ))}
    </div>
  );
};

// components/EmptyState.tsx

export const EmptyState = () => {
  return (
    <div className="empty-state text-center py-12">
      <div className="text-gray-400 mb-4">
        <svg className="w-24 h-24 mx-auto" /* empty folder icon */ />
      </div>
      <h3 className="text-lg font-semibold mb-2">No images yet</h3>
      <p className="text-gray-600 mb-4">
        Upload your first image to get started
      </p>
      <button className="btn btn-primary">
        Upload Image
      </button>
    </div>
  );
};


// services/api/media.service.test.ts

import { mediaService } from './media.service';
import { apiClient } from './client';

jest.mock('./client');

describe('mediaService', () => {
  describe('listUserImages', () => {
    it('should fetch images with default params', async () => {
      const mockResponse = {
        data: {
          items: [],
          hasMore: false,
        },
      };

      (apiClient.get as jest.Mock).mockResolvedValue(mockResponse);

      const result = await mediaService.listUserImages();

      expect(apiClient.get).toHaveBeenCalledWith('/api/media/images?');
      expect(result).toEqual(mockResponse.data);
    });

    it('should include query parameters', async () => {
      const mockResponse = { data: { items: [], hasMore: false } };
      (apiClient.get as jest.Mock).mockResolvedValue(mockResponse);

      await mediaService.listUserImages({
        limit: 10,
        prefix: 'covers/',
        signed: true,
      });

      expect(apiClient.get).toHaveBeenCalledWith(
        '/api/media/images?limit=10&prefix=covers%2F&signed=true'
      );
    });
  });
});
